const body = $input.first().json.body;

if (!body?.entry?.[0]?.changes?.[0]?.value?.messages?.[0]) {
  return [{ json: { skip: true } }];
}

const change = body.entry[0].changes[0].value;
const message = change.messages[0];
const contact = change.contacts?.[0];

if (message.type !== 'text') {
  return [{ json: {
    skip: false,
    phoneNumber: message.from,
    response: 'I can only process text messages. Please type your timetable query.',
    isUnsupported: true
  }}];
}

return [{ json: {
  skip: false,
  isUnsupported: false,
  phoneNumber: message.from,
  messageId: message.id,
  query: message.text.body,
  contactName: contact?.profile?.name || 'Student',
  timestamp: message.timestamp,
  phoneNumberId: body.entry[0].changes[0].value.metadata.phone_number_id
}}];

// Same preprocessor as main workflow
const input = $input.first().json;
const query = (input.query || '').trim();
const queryLower = query.toLowerCase();

const sectionMap = [
  { patterns: ['sd b', 'software dev b'], tab: 'CSE_SD_Sec_B', name: 'Software Development B' },
  { patterns: ['sd', 'software dev', 'software development'], tab: 'CSE_SD_Sec_A', name: 'Software Development A' },
  { patterns: ['ai b', 'aiml b'], tab: 'CSE_AIML_Sec_B', name: 'AIML B' },
  { patterns: ['ai', 'aiml', 'artificial intelligence', 'machine learning', 'ml'], tab: 'CSE_AIML_Sec_A', name: 'AIML A' },
  { patterns: ['cys b', 'cyber b'], tab: 'CSE_CyberSec_Sec_B', name: 'Cyber Security B' },
  { patterns: ['cys', 'cyber', 'cyber security', 'cybersec'], tab: 'CSE_CyberSec_Sec_A', name: 'Cyber Security A' },
  { patterns: ['ibm'], tab: 'CSE_IBM_Sec_A', name: 'IBM A' },
  { patterns: ['xebia'], tab: 'CSE_Xebia_Sec_A', name: 'Xebia A' }
];

const dayMap = {
  'mon': 'Monday', 'monday': 'Monday', 'tue': 'Tuesday', 'tuesday': 'Tuesday',
  'wed': 'Wednesday', 'wednesday': 'Wednesday', 'thu': 'Thursday', 'thursday': 'Thursday',
  'fri': 'Friday', 'friday': 'Friday', 'sat': 'Saturday', 'saturday': 'Saturday'
};

const dayToCol = {
  'Monday': 'B', 'Tuesday': 'C', 'Wednesday': 'D',
  'Thursday': 'E', 'Friday': 'F', 'Saturday': 'G'
};

const timeToRow = {
  '9': 3, '10': 4, '11': 5, '12': 6, '13': 7, '1': 7, '14': 8, '2': 8, '15': 9, '3': 9, '16': 10, '4': 10
};

let detectedSection = null, detectedSectionName = null, detectedDay = null;

for (const sec of sectionMap) {
  for (const p of sec.patterns) {
    if (queryLower.includes(p)) { detectedSection = sec.tab; detectedSectionName = sec.name; break; }
  }
  if (detectedSection) break;
}

const now = new Date();
if (['today','aaj'].some(w => queryLower.includes(w))) {
  detectedDay = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][now.getDay()];
} else if (['tomorrow','kal'].some(w => queryLower.includes(w))) {
  const t = new Date(now); t.setDate(t.getDate()+1);
  detectedDay = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][t.getDay()];
} else {
  for (const [k,v] of Object.entries(dayMap)) { if (queryLower.includes(k)) { detectedDay = v; break; } }
}

let detectedRow = null;
const timeMatch = queryLower.match(/(\d{1,2})\s*(?::|\s)?\s*(\d{2})?\s*(am|pm)?/);
if (timeMatch) {
  let h = parseInt(timeMatch[1]);
  if (timeMatch[3]==='pm' && h!==12) h+=12;
  if (timeMatch[3]==='am' && h===12) h=0;
  detectedRow = timeToRow[String(h)] || null;
}

let cellRange = null, fullDayRange = null;
if (detectedSection && detectedDay) {
  const col = dayToCol[detectedDay];
  if (col) {
    if (detectedRow) cellRange = `${detectedSection}!${col}${detectedRow}`;
    fullDayRange = `${detectedSection}!${col}3:${col}10`;
  }
}

return [{ json: {
  ...input,
  originalQuery: query, detectedSection, detectedSectionName, detectedDay,
  detectedRow, cellRange, fullDayRange,
  needsSection: !detectedSection, needsDay: !detectedDay
}}];

